from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=max(set(x for row in grid for x in row), key=lambda c:sum(row.count(c) for row in grid))
    out=[[bg]*w for _ in range(h)]
    seen=set()
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for dy in (-1,0,1):
            for dx in (-1,0,1):
              ny,nx=y+dy,x+dx
              if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==col:
                seen.add((ny,nx)); q.append((ny,nx))
        ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
        y0,y1=min(ys),max(ys); x0,x1=min(xs),max(xs)
        area=(y1-y0+1)*(x1-x0+1)
        if len(comp)>=6 and (y1-y0+1)>=2 and (x1-x0+1)>=2 and len(comp)/area>=0.5:
          for yy in range(y0,y1+1):
            for xx in range(x0,x1+1): out[yy][xx]=col
    return out
